const SavedRules={STORAGE_KEY:'redis-acl-builder-saved-rules',elements:{saveButton:null,savedRulesSection:null,savedRulesContent:null,aclRule:null},init(){this.findElements();this.loadSavedRules();this.updateSaveButtonState();this.setupEventListeners();},findElements(){this.elements.saveButton=document.getElementById('saveRuleBtn');this.elements.savedRulesSection=document.getElementById('savedRulesSection');this.elements.savedRulesContent=document.getElementById('savedRulesContent');this.elements.aclRule=document.getElementById('aclRule');if(!this.elements.saveButton||!this.elements.savedRulesSection||!this.elements.savedRulesContent||!this.elements.aclRule){console.error('Required elements not found for saved rules');return false;}
return true;},setupEventListeners(){if(this.elements.aclRule){this.elements.aclRule.addEventListener('input',(event)=>{const isProgrammaticUpdate=event.target.dataset.programmaticUpdate==='true';if(!isProgrammaticUpdate){this.updateSaveButtonState();}else{setTimeout(()=>{this.updateSaveButtonState();},100);}});}},updateSaveButtonState(){if(!this.elements.saveButton)return;const lastCommittedRule=this.getCommittedRule();const hasCommittedContent=lastCommittedRule&&lastCommittedRule.trim().length>0;this.elements.saveButton.disabled=!hasCommittedContent;},getCommittedRule(){try{return localStorage.getItem('redis-acl-builder-rule')||'';}catch(error){console.warn('Failed to load committed rule:',error);return'';}},saveCurrentRule(){if(!this.elements.aclRule)return;const ruleText=this.elements.aclRule.value.trim();if(!ruleText){this.showNotification('Cannot save empty ACL rule','error');return;}
const savedRules=this.getSavedRules();if(savedRules.includes(ruleText)){this.showNotification('This ACL rule is already saved','warning');return;}
savedRules.push(ruleText);this.setSavedRules(savedRules);this.renderSavedRules();this.showNotification('ACL rule saved successfully','success');},loadSavedRule(ruleText){if(!this.elements.aclRule)return;this.elements.aclRule.value=ruleText;const event=new Event('input',{bubbles:true});this.elements.aclRule.dispatchEvent(event);this.updateSaveButtonState();this.showNotification('ACL rule loaded','success');},deleteSavedRule(ruleText){const savedRules=this.getSavedRules();const index=savedRules.indexOf(ruleText);if(index>-1){savedRules.splice(index,1);this.setSavedRules(savedRules);this.renderSavedRules();this.showNotification('ACL rule deleted','success');}},getSavedRules(){try{const saved=localStorage.getItem(this.STORAGE_KEY);return saved?JSON.parse(saved):[];}catch(error){console.warn('Failed to load saved rules:',error);return[];}},setSavedRules(rules){try{localStorage.setItem(this.STORAGE_KEY,JSON.stringify(rules));}catch(error){console.warn('Failed to save rules:',error);}},loadSavedRules(){this.renderSavedRules();},renderSavedRules(){if(!this.elements.savedRulesSection||!this.elements.savedRulesContent)return;const savedRules=this.getSavedRules();if(savedRules.length===0){this.elements.savedRulesSection.style.display='none';this.triggerScrollCheck();return;}
this.elements.savedRulesSection.style.display='block';this.elements.savedRulesContent.textContent='';savedRules.forEach(rule=>{const ruleItem=document.createElement('div');ruleItem.className='saved-rule-item';const ruleButton=document.createElement('button');ruleButton.type='button';ruleButton.className='saved-rule-button';ruleButton.textContent=rule;ruleButton.title=`Load ACL rule: ${rule}`;ruleButton.addEventListener('click',()=>{this.loadSavedRule(rule);});const deleteButton=document.createElement('button');deleteButton.type='button';deleteButton.className='saved-rule-delete';deleteButton.textContent='✕';deleteButton.title=`Delete saved rule: ${rule}`;deleteButton.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();this.deleteSavedRule(rule);});ruleItem.appendChild(ruleButton);ruleItem.appendChild(deleteButton);this.elements.savedRulesContent.appendChild(ruleItem);});this.triggerScrollCheck();},triggerScrollCheck(){if(typeof window.checkQuickExamplesScroll==='function'){setTimeout(()=>{window.checkQuickExamplesScroll();},50);}},showNotification(message,type='info'){if(window.showNotification){window.showNotification(message,type);}else{console.log(`${type.toUpperCase()}: ${message}`);}}};window.saveACLRule=()=>SavedRules.saveCurrentRule();export default SavedRules;